// Os versículos do dia ficam em versiculos.js (365, um para cada dia do ano).
// Mostra o versículo do dia: avança um por dia e percorre a lista inteira antes de reiniciar.
function renderVersiculo(){
  const el = document.getElementById("versiculo");
  if(!el) return;
  const agora = new Date();
  const diaDoAno = Math.floor((agora - new Date(agora.getFullYear(), 0, 1)) / 864e5);
  const v = VERSICULOS[diaDoAno % VERSICULOS.length];
  el.innerHTML =
    '<h3>Versículo do Dia</h3>' +
    `<p class="vref">${v.r}</p>` +
    `<blockquote>${v.t}</blockquote>` +
    `<p class="vctx"><b>Contexto:</b> ${v.c}</p>` +
    `<div class="vleg"><b>Pesos, medidas e geografia</b><ul>${v.l.map(x=>`<li>${x}</li>`).join("")}</ul></div>` +
    '<small>Texto bíblico: João Ferreira de Almeida</small>';
}
// Junta os nomes de um horário: "A / B" (um casal continua sendo um único registro)
const nomeSlot = (l) => {
  const x = l || {};
  const ns = Array.isArray(x.nomes) ? x.nomes.filter(Boolean) : [];
  return ns.length ? ns.join(" / ") : (x.nome || "");
};
