// Rodapé fixo no celular (Voltar / Início / admin)
function initFooter() {
  if (document.querySelector(".appfoot")) return;
  const naAdmin = /(^|\/)admin(\.html)?$/.test(location.pathname);
  const b = document.createElement("div");
  b.className = "appfoot";
  b.innerHTML =
    '<button type="button" class="s" id="fvoltar">Voltar</button><a id="fhome" href="/">Início</a>' +
    (naAdmin ? "" : `<a class="admic" href="/admin.html" title="Administração" aria-label="Administração">${ICONE_ADMIN}</a>`);
  document.body.append(b);
  b.querySelector("#fvoltar").onclick = () => { if (history.length > 1) history.back(); else location.href = "/"; };
  
  // Observador para remover o selo Netlify se ele for injetado depois (brute-force).
  // O selo atual é um iframe com id "nl-badge-frame" (não contém "netlify" no nome).
  const removerNetlify = () => {
    const selos = document.querySelectorAll('#nl-badge-frame, iframe[id^="nl-"], iframe[title*="Netlify"], #netlify-drawer, .netlify-drawer, [data-netlify-identity-menu], .netlify-badge, .netlify-badge-wrapper, [id*="netlify"], [class*="netlify"], iframe[src*="netlify"], div[class*="netlify"]');
    selos.forEach(s => {
      try {
        s.style.setProperty("display", "none", "important");
        s.style.setProperty("visibility", "hidden", "important");
        s.style.setProperty("opacity", "0", "important");
        s.style.setProperty("pointer-events", "none", "important");
        s.style.setProperty("position", "fixed", "important");
        s.style.setProperty("left", "-9999px", "important");
        s.remove();
      } catch (e) {}
    });
  };
  removerNetlify();
  setInterval(removerNetlify, 1000); // Tenta remover a cada segundo também
  const obs = new MutationObserver(removerNetlify);
  obs.observe(document.body, { childList: true, subtree: true });
}
const pad=n=>String(n).padStart(2,"0");
